/**
 * Raised when a create request supplies a telephone number whose normalized (digits-only) value is
 * already used by another owner. Carries the conflicting value so the API can report the rejection
 * back to the client.
 */
public class DuplicateTelephoneException extends RuntimeException {

    private final String telephone;

    public DuplicateTelephoneException(String telephone) {
        super("An owner with telephone '" + telephone + "' already exists");
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }
}

